import {useEffect,useState} from 'react';
import {defineLocalTool,type LocalToolJson,type LocalToolProps,type LocalToolSnapshot} from '@/engines/local/sdk';
type State={version:1;notes:string};
function valid(value:LocalToolJson):value is State{return Boolean(value&&typeof value==='object'&&!Array.isArray(value)&&value.version===1&&typeof value.notes==='string');}
function Notebook({client}:LocalToolProps<State>){const [snapshot,setSnapshot]=useState<LocalToolSnapshot<State>|null>(null),[notes,setNotes]=useState(''),[message,setMessage]=useState('');useEffect(()=>{let active=true;void client.read().then(value=>{if(active){setSnapshot(value);setNotes(value.data.notes);}});return()=>{active=false;};},[client]);return <section><textarea aria-label="SDK notes" value={notes} onChange={event=>setNotes(event.target.value)}/><button disabled={!snapshot} onClick={()=>{if(snapshot)void client.save({version:1,notes},snapshot.revision).then(value=>{setSnapshot(value);setMessage('Saved');}).catch(()=>setMessage('Conflict: draft retained'));}}>Save SDK notes</button><p role="status">{message}</p></section>;}
export default defineLocalTool<State>({namespace:'tests.notebook',name:{en:'Synthetic notebook',es:'Cuaderno sintético'},description:{en:'An isolated trusted source fixture.',es:'Un ejemplo de código fuente local aislado.'},initialState:{version:1,notes:''},validateState:valid,component:Notebook});
